1: //! 评测夹具：切点/锚点的「配对」口径。
2: //!
3: //! 覆盖四条路径，任何一条没修都会红：
4: //! 1. 自动压缩 `plan_if_needed`：切点不许把 function_call 和它的 output 拆到两侧；
5: //! 2. 手动压缩 `plan_manual`：同一条算法，两个入口都要修；
6: //! 3. 分叉 `nearest_safe_cut`：不能落在一次调用的中间；
7: //! 4. 搜索索引 `build_documents`：连续两个锚点后，序号口径仍与重放一致。
8: 
9: use shaniu_lib::compaction::{plan_if_needed, plan_manual, Target};
10: use shaniu_lib::model_client::{HistoryItem, Role};
11: use shaniu_lib::rollout::resume::nearest_safe_cut;
12: use shaniu_lib::rollout::RolloutItem;
13: use shaniu_lib::session_query::documents::build_documents;
14: 
15: fn msg(text: &str) -> HistoryItem {
16:     HistoryItem::Message { role: Role::User, text: text.into(), reasoning: None }
17: }
18: 
19: fn big_msg() -> HistoryItem {
20:     msg(&"m".repeat(400))
21: }
22: 
23: fn call(id: &str) -> HistoryItem {
24:     HistoryItem::FunctionCall { name: "run".into(), arguments: "a".repeat(400), call_id: id.into() }
25: }
26: 
27: fn output(id: &str) -> HistoryItem {
28:     HistoryItem::FunctionCallOutput { call_id: id.into(), output: "o".repeat(400) }
29: }
30: 
31: fn archive(item: HistoryItem) -> RolloutItem {
32:     RolloutItem::ResponseItem { item, at_ms: 1 }
33: }
34: 
35: /// 保留额度 300 tokens：朴素切法是 3，会把 index 2 的 call 压掉、留下 index 3 的 output。
36: #[test]
37: fn manual_compaction_does_not_split_a_call_from_its_output() {
38:     let items = vec![big_msg(), big_msg(), call("c1"), output("c1"), big_msg(), big_msg()];
39:     let target = plan_manual(&items, 1000).expect("应该可以压缩");
40:     assert_eq!(
41:         target,
42:         Target { range_start: 0, range_end: 2 },
43:         "压缩区间把 call 和 output 拆开了：{target:?}"
44:     );
45: }
46: 
47: /// 同一条算法在自动路径上也要成立——只改 plan_manual 会在这里红。
48: #[test]
49: fn automatic_compaction_does_not_split_a_call_from_its_output() {
50:     let items = vec![big_msg(), big_msg(), call("c1"), output("c1"), big_msg(), big_msg()];
51:     let target = plan_if_needed(50_000, &items, 1000).expect("超过预算，应该压缩");
52:     assert_eq!(
53:         target,
54:         Target { range_start: 0, range_end: 2 },
55:         "自动压缩把 call 和 output 拆开了：{target:?}"
56:     );
57: }
58: 
59: /// 配对起点就在 0：往回缩会变成空压缩，只能把整对一起压掉。
60: #[test]
61: fn a_pair_at_the_start_is_compacted_whole_instead_of_left_empty() {
62:     let items = vec![call("c2"), output("c2"), big_msg(), big_msg()];
63:     let target = plan_if_needed(50_000, &items, 1000).expect("超过预算，应该压缩");
64:     assert_eq!(
65:         target,
66:         Target { range_start: 0, range_end: 2 },
67:         "配对从 0 开始时必须整对压掉，而不是返回空区间：{target:?}"
68:     );
69: }
70: 
71: /// 切点本来就落在两条完整配对之间时，不许借机多压。
72: #[test]
73: fn a_clean_boundary_is_left_where_the_budget_put_it() {
74:     let items = vec![big_msg(), big_msg(), call("c3"), output("c3"), big_msg(), big_msg()];
75:     let target = plan_manual(&items, 667).expect("应该可以压缩");
76:     assert_eq!(
77:         target,
78:         Target { range_start: 0, range_end: 4 },
79:         "干净切点被改动了：{target:?}"
80:     );
81: }
82: 
83: /// 分叉：want=2 会留下一条有 call 无 output 的尾巴，必须回退到 1。
84: #[test]
85: fn fork_cut_never_lands_inside_a_tool_call() {
86:     let items = vec![archive(big_msg()), archive(call("c4")), archive(output("c4")), archive(big_msg())];
87:     assert_eq!(nearest_safe_cut(&items, 2), 1, "分叉切点落在调用中间");
88: }
89: 
90: /// 连续两个锚点：第二个锚点压的是第一段摘要，后面的调用/输出必须仍是 current。
91: #[test]
92: fn consecutive_compactions_keep_the_index_numbering_aligned() {
93:     let items = vec![
94:         archive(msg("alpha")),
95:         archive(call("c5")),
96:         archive(output("c5")),
97:         RolloutItem::Compacted { range_start: 0, range_end: 1, summary: "s1".into() },
98:         archive(msg("beta")),
99:         archive(msg("gamma")),
100:         RolloutItem::Compacted { range_start: 0, range_end: 1, summary: "s2".into() },
101:     ];
102:     let docs = build_documents(&items, 1_700_000_000_000);
103:     let surface = |seq: i64| {
104:         docs.iter()
105:             .find(|doc| doc.seq == seq)
106:             .unwrap_or_else(|| panic!("缺少 seq={seq} 的文档"))
107:             .surface
108:     };
109:     assert_eq!(surface(0), "shadowed", "alpha 已被第一次压缩取代");
110:     assert_eq!(surface(2), "current", "call 与 output 都没被任何锚点压掉，不该被标成 shadowed");
111:     assert_eq!(surface(3), "current", "output 与 call 成对保留，不该错位");
112:     assert_eq!(surface(8), "current", "beta 在两个锚点之后仍然可见");
113: }

（文件结束：共 113 行）

1: //! token 预算判定 + 历史摘要压缩（SH-032）。
2: //!
3: //! 判据与形态取自 codex 的**本地实现**那条路（`core/src/compact.rs`），但锚点语义
4: //! 必须服从我们自己的文档：04 §3.1 规定 `Compacted` 存 `{range_start, range_end, summary}`
5: //! 这个**区间**形态，SH-031 的回放也已经建立在「用 summary 替换 history 的对应区间」上。
6: //! codex 那边存的是替换后的完整历史（`replacement_history`），照抄会把已交付的
7: //! resume/fork 语义拆掉——所以这里刻意不抄。
8: //!
9: //! 本模块刻意**不**依赖 `agent_loop`：它只做纯计算（估算、判据、区间、请求构造、
10: //! 摘要提取），发请求与写档案都留在循环层。否则 `agent_loop → compaction → agent_loop`
11: //! 会成环，而 §2.3.1 里也没有这条反向边。
12: 
13: use crate::model_client::{HistoryItem, Role};
14: 
15: /// 4 字节 ≈ 1 token 的粗估口径，与 codex `utils/string/src/truncate.rs:6` 同参数。
16: ///
17: /// 没有引真实 tokenizer（codex 全仓也没有：`tiktoken`/`cl100k`/`o200k` 零命中）。
18: /// 预算判据要的是"该收口了没有"这个量级，不是精确计费；为它背一个几百 KB 的词表
19: /// 与逐模型词表选择，换来的精度用不上。
20: const APPROX_BYTES_PER_TOKEN: usize = 4;
21: 
22: /// 压缩后**保留**的额度占预算的比例。
23: ///
24: /// 取 30% 而不是更高：压缩完成后历史只占预算三成，剩下七成留给新一轮工具输出。
25: /// 留得太满会让下一轮立刻再次触发压缩，等于把一次摘要的代价反复付。
26: /// 这条是设计选择，04 §6.4 只规定了摘要必含字段、没规定保留比例。
27: const KEEP_RATIO_PERCENT: usize = 30;
28: 
29: /// 模型行未声明 `context_window` 时用于推导压缩阈值的保守窗口。
30: ///
31: /// 取 128K 而不是乐观值：窗口未知时宁可早压（多花一次摘要），也不能沿用 50 万预算——
32: /// 那等于永不压缩，128K 模型跑到一半直接 400，代价比多压几次大得多。
33: pub const FALLBACK_CONTEXT_WINDOW: usize = 128_000;
34: 
35: /// 单个上下文窗口允许占用的量：窗口 × 80%，留 20% 给下一轮回复与工具结果。
36: fn window_allowance(window: usize) -> usize {
37:     let window = if window == 0 { FALLBACK_CONTEXT_WINDOW } else { window };
38:     window.saturating_mul(4) / 5
39: }
40: 
41: /// 自动压缩阈值：`min(配置预算, 窗口 × 80%)`。
42: ///
43: /// - `configured == 0`：显式关闭压缩，保持 0（不替用户改主意）；
44: /// - `window == 0`（模型未声明）：按 [`FALLBACK_CONTEXT_WINDOW`] 推导，调用方负责告警；
45: /// - 其余：留 20% 给下一轮回复与工具结果。
46: ///
47: /// 回合内自动压缩与手动 `/compact` **必须**共用这一份口径（见 [`manual_token_budget`]）：
48: /// 两处各算一遍时，手动路径拿到的是未经窗口裁剪的配置值，会出现「压完仍然超窗口」。
49: pub fn compact_token_budget(configured: usize, window: usize) -> usize {
50:     if configured == 0 {
51:         return 0;
52:     }
53:     configured.min(window_allowance(window))
54: }
55: 
56: /// 手动压缩阈值：用户显式要求压缩时，`configured == 0` 不能解释成「关掉」。
57: ///
58: /// 用 0 直接进 [`plan_manual`] 会算出「保留 0 条尾部」，把历史压到只剩最后一条——
59: /// 那不是任何人的预期。这里的 0 表示「不设配置上限」，于是按窗口算：与自动路径
60: /// 同一个窗口口径，只是不因为「关掉自动压缩」而拒绝用户显式要求的这一次。
61: pub fn manual_token_budget(configured: usize, window: usize) -> usize {
62:     if configured == 0 {
63:         return window_allowance(window);
64:     }
65:     configured.min(window_allowance(window))
66: }
67: 
68: /// 摘要提示词。五个必含字段逐条来自 04 §6.4：
69: /// 任务目标 / 已完成事项 / 关键文件与改动 / 未解决问题 / 下一步。
70: ///
71: /// 少了任何一条，接手的模型就会去重做已经做过的事，或者忘掉用户已经给过的约束——
72: /// 那正是"压缩丢失细节"（01 §3 ADR-001 风险表）的实际发生方式。
73: pub const SUMMARIZATION_PROMPT: &str = "请把上面这段对话与工具执行历史压缩成一份交接摘要，交给另一个模型继续这个任务。\
74: 摘要必须依次包含以下五项，每项一行到数行：\n\
75: 1. 任务目标：用户最初要什么，以及过程中已经变更过的约束。\n\
76: 2. 已完成事项：确实做完并有结果可查的动作。\n\
77: 3. 关键文件与改动：被读过、被改过的文件路径与改动要点。\n\
78: 4. 未解决问题：失败过、被拒绝过、或结果与预期不符的事项。\n\
79: 5. 下一步：接手后应该立刻做的事。\n\
80: 只输出这五项内容本身，不要前言、不要解释你做了压缩。";
81: 
82: /// 一次压缩的区间：`[range_start, range_end)` 的历史将被 summary 取代。
83: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
84: pub struct Target {
85:     pub range_start: usize,
86:     pub range_end: usize,
87: }
88: 
89: /// 一次压缩的唯一标识：毫秒时间戳 + 进程内序号。
90: ///
91: /// 用途只是把 `compaction_started / summarized / ended` 三条事件配成一组（含日志回放）。
92: /// 不引 ULID：进程内序号 + 单调时间戳足以保证同一会话的事件流不撞号，而这个 id
93: /// 不参与任何持久化键或安全判定。
94: pub fn new_id() -> String {
95:     static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
96:     let now = std::time::SystemTime::now()
97:         .duration_since(std::time::UNIX_EPOCH)
98:         .map(|d| d.as_millis())
99:         .unwrap_or(0);
100:     format!(
101:         "cmp-{now}-{}",
102:         SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
103:     )
104: }
105: 
106: pub fn approx_tokens(text: &str) -> usize {
107:     text.len().div_ceil(APPROX_BYTES_PER_TOKEN)
108: }
109: 
110: /// 一条条目的模型可见量。只算内容字节——id、外层 JSON 转义与传输元数据都不进上下文，
111: /// 把它们算进去会让预算系统性偏紧，表现为"明明还装得下却开始压缩"。
112: pub fn item_tokens(item: &HistoryItem) -> usize {
113:     match item {
114:         HistoryItem::Message { text, reasoning, .. } => {
115:             approx_tokens(text) + reasoning.as_deref().map(approx_tokens).unwrap_or_default()
116:         }
117:         HistoryItem::FunctionCall { name, arguments, .. } => {
118:             approx_tokens(name) + approx_tokens(arguments)
119:         }
120:         HistoryItem::FunctionCallOutput { output, .. } => approx_tokens(output),
121:         // 图片字节不在历史里，按 view_image 记下的分辨率估算值计入预算。
122:         HistoryItem::ImageMessage { text, images, .. } => {
123:             approx_tokens(text) + images.iter().map(|image| image.tokens as usize).sum::<usize>()
124:         }
125:     }
126: }
127: 
128: pub fn history_tokens(items: &[HistoryItem]) -> usize {
129:     items.iter().map(item_tokens).sum()
130: }
131: 
132: /// 从尾部往前装，算出「保留哪些」的切点：`[0, range_end)` 是要压掉的区间。
133: ///
134: /// 三条不变量是这层抽象**唯一**的存在理由，改任何一条都会让某条路径的行为变坏：
135: /// 1. **严格大于**：判据是 `kept + cost > keep_allowance`，保留额度**刚好**装得下一条时
136: ///    必须留下它。写成 `>=` 会在边界上少留一条，压得比配置口径更狠。
137: /// 2. **至少留一条**：`split >= len` 时钳到 `len - 1`。全压掉会让下一轮看到的历史只剩
138: ///    一段摘要，模型连"刚才那条命令的输出是什么"都无从得知。
139: /// 3. **钳到 1**：`range_end` 至少为 1。判据已经说超预算、而按字节估算整段都装得进
140: ///    保留额度时（观测值含推理 token 与工具声明开销，字节估算看不见），退化成压掉
141: ///    最旧的一条让每轮稳定回收一点，而不是返回 `[0,0)` 空转。
142: ///
143: /// 调用方各自的门槛（预算是否为 0、条数是否够、阈值是否达到、`keep_allowance` 怎么算）
144: /// **不在这里**：自动与手动两条路径的门槛本就不同，合进来就得加参数分叉，得不偿失。
145: /// 前置条件：`items.len() >= 2`，由调用方保证。
146: fn tail_target(items: &[HistoryItem], keep_allowance: usize) -> Target {
147:     let mut kept = 0usize;
148:     let mut split = items.len();
149:     for index in (0..items.len()).rev() {
150:         let cost = item_tokens(&items[index]);
151:         // 不变量①：严格大于——刚好装得下的那条必须留下。
152:         if kept + cost > keep_allowance {
153:             split = index + 1;
154:             break;
155:         }
156:         kept += cost;
157:         split = index;
158:     }
159:     // 不变量②：至少留最后一条不压，哪怕它自己就超了保留额度。
160:     if split >= items.len() {
161:         split = items.len() - 1;
162:     }
163:     // 不变量③：绝不空压。
164:     Target { range_start: 0, range_end: split.max(1) }
165: }
166: 
167: /// 是否需要压缩，以及压哪一段。
168: ///
169: /// `observed_tokens` 是上一次采样端点报回的真实用量（含推理 token 与工具声明开销，
170: /// 这两项字节估算都看不见）。判据取 `max(观测值, 全量估算)`：
171: /// 观测值可能落后于本轮刚追加的大块工具输出，估算值又系统性低估协议开销——
172: /// 两者各有盲区，而**低估的代价是撞上上下文溢出**（请求直接失败），
173: /// 高估的代价只是提前压一次。所以取较大值。
174: pub fn plan_if_needed(observed_tokens: usize, items: &[HistoryItem], budget: usize) -> Option<Target> {
175:     if budget == 0 {
176:         return None;
177:     }
178:     if items.len() < 2 {
179:         // 少于两条没什么可压：把唯一一条压成摘要，等于把任务目标本身交给一次
180:         // 可能失败的总结请求去保管。
181:         return None;
182:     }
183:     let estimate = history_tokens(items);
184:     if observed_tokens.max(estimate) < budget {
185:         return None;
186:     }
187: 
188:     // 从尾部往前装，装不下的那些进摘要。三条不变量见 [`tail_target`]。
189:     Some(tail_target(items, budget.saturating_mul(KEEP_RATIO_PERCENT) / 100))
190: }
191: 
192: /// 手动压缩（`/compact`，SH-115）的目标规划：与 [`plan_if_needed`] 同一条尾部保留
193: /// 算法，但**不看预算阈值**——用户显式要求压缩就是要现在压，哪怕当前用量还低。
194: /// 预算仍决定保留多少（budget=0 时只留最后一条：预算关闭说明用户不想要自动压缩，
195: /// 但手动命令的语义不变）。
196: ///
197: /// 与 [`plan_if_needed`] 的另两点差异：
198: /// - 少于两条返回 `None`（没有可压的，调用方回 "No compactable history yet."）；
199: ///   不像自动路径那样退化压最旧一条——唯一一条就是任务本身，压掉它没有意义。
200: /// - 全部装进保留额度时（split==0）钳到 1：手动命令既然发出了，至少压掉最旧一条，
201: ///   与 [`plan_if_needed`] 的退化口径一致，而不是空转返回"没压任何东西"。
202: pub fn plan_manual(items: &[HistoryItem], budget: usize) -> Option<Target> {
203:     if items.len() < 2 {
204:         return None;
205:     }
206:     let keep_allowance = if budget == 0 {
207:         0
208:     } else {
209:         budget.saturating_mul(KEEP_RATIO_PERCENT) / 100
210:     };
211:     Some(tail_target(items, keep_allowance))
212: }
213: 
214: /// 构造总结请求：被压区间的全部条目 + 末尾一条总结指令。
215: ///
216: /// 只送被压区间而不是整段历史：保留段马上还要原样用，把它再喂一遍只会让这次
217: /// 总结请求本身去撞预算。
218: pub fn build_request(items: &[HistoryItem], target: &Target) -> Vec<HistoryItem> {
219:     let mut request = items[target.range_start..target.range_end].to_vec();
220:     request.push(HistoryItem::Message {
221:         role: Role::User,
222:         text: SUMMARIZATION_PROMPT.to_string(),
223:         reasoning: None,
224:     });
225:     request
226: }
227: 
228: /// 从总结响应里取摘要。空摘要必须报出来而不是当成成功：
229: /// 拿空串写锚点，回放时那段历史就被替换成"什么都没有"，是静默丢上下文。
230: pub fn extract_summary(reply_text: &str) -> Result<String, String> {
231:     let trimmed = reply_text.trim();
232:     if trimmed.is_empty() {
233:         return Err("压缩失败：总结请求没有返回可用摘要".to_string());
234:     }
235:     Ok(trimmed.to_string())
236: }
237: 
238: #[cfg(test)]
239: mod tests {
240:     use super::*;
241: 
242:     fn msg(role: Role, text: &str) -> HistoryItem {
243:         HistoryItem::Message { role, text: text.to_string(), reasoning: None }
244:     }
245: 
246:     fn call(id: &str, args: &str) -> HistoryItem {
247:         HistoryItem::FunctionCall {
248:             name: "unified_exec".into(),
249:             arguments: args.into(),
250:             call_id: id.into(),
251:         }
252:     }
253: 
254:     fn out(id: &str, output: &str) -> HistoryItem {
255:         HistoryItem::FunctionCallOutput { call_id: id.into(), output: output.into() }
