192: /// fork 的结果：新档案路径 + 实际采用的截断点 + 因不安全而被回退掉的条目数。
193: #[derive(Debug, Clone, PartialEq)]
194: pub struct Forked {
195:     pub path: PathBuf,
196:     pub new_agent_id: String,
197:     pub kept_items: usize,
198:     pub dropped_items: usize,
199: }
200: 
201: /// 复制档案到 `<dir>/<new_agent_id>.jsonl`，截断到最近安全点，并写入带 `parent_id` 的新首行。
202: ///
203: /// 原档案**只读**：fork 出错的代价不该由父会话的历史承担。
204: pub fn fork(src: &Path, dir: &Path, new_agent_id: &str, want_items: usize) -> Result<Forked, RolloutError> {
205:     let archive = rollout::read(src)?;
206:     let parent = match &archive.meta {
207:         RolloutItem::SessionMeta { agent_id, config_snapshot, .. } => (agent_id.clone(), config_snapshot.clone()),
208:         other => return Err(RolloutError::NoSessionMeta(format!("{:?}", other))),
209:     };
210:     let keep = nearest_safe_cut(&archive.items, want_items);
211:     std::fs::create_dir_all(dir).map_err(|e| RolloutError::Io(format!("{dir:?}: {e}")))?;
212:     let path = dir.join(format!("{new_agent_id}.jsonl"));
213:     let meta = RolloutItem::SessionMeta {
214:         session_id: new_agent_id.to_string(),
215:         agent_id: new_agent_id.to_string(),
216:         parent_id: Some(parent.0),
217:         created_at: SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as u64).unwrap_or_default(),
218:         config_snapshot: parent.1,
219:     };
220:     let writer = RolloutWriter::create(dir, &meta)?;
221:     for item in &archive.items[..keep] {
222:         writer.append(item)?;
223:     }
224:     Ok(Forked {
225:         path,
226:         new_agent_id: new_agent_id.to_string(),
227:         kept_items: keep,
228:         dropped_items: want_items.saturating_sub(keep),
229:     })
230: }
